import * as React from 'react'
import { useId } from 'react'

import { cx } from '~/lib/cx'
import styles from './switch.module.scss'

export type SwitchSize = 'sm' | 'md' | 'lg'

const SIZE: Record<SwitchSize, string> = {
  sm: styles.sm,
  md: '',
  lg: styles.lg,
}

export interface SwitchProps {
  checked?: boolean
  defaultChecked?: boolean
  onCheckedChange?: (checked: boolean) => void
  label?: React.ReactNode
  description?: string
  /** Put the switch after the label instead of before it. */
  reverse?: boolean
  size?: SwitchSize
  disabled?: boolean
  id?: string
  name?: string
  value?: string
  className?: string
}

export function Switch({
  checked: checkedProp,
  defaultChecked = false,
  onCheckedChange,
  label,
  description,
  reverse = false,
  size = 'md',
  disabled = false,
  id: idProp,
  name,
  value,
  className,
}: SwitchProps) {
  const generatedId = useId()
  const id = idProp ?? generatedId
  const labelId = `${id}-label`
  const descriptionId = description ? `${id}-description` : undefined

  const [uncontrolled, setUncontrolled] = React.useState(defaultChecked)
  const checked = checkedProp ?? uncontrolled

  const toggle = () => {
    const next = !checked
    if (checkedProp === undefined) setUncontrolled(next)
    onCheckedChange?.(next)
  }

  const control = (
    <button
      type="button"
      role="switch"
      id={id}
      name={name}
      value={value}
      aria-checked={checked}
      aria-describedby={descriptionId}
      aria-label={label ? undefined : 'Toggle'}
      aria-labelledby={label ? labelId : undefined}
      disabled={disabled}
      className={cx(styles.switch, SIZE[size], className)}
      onClick={toggle}
    >
      <span className={styles.thumb} />
    </button>
  )

  if (!label && !description) return control

  return (
    <div className={styles.field} data-reverse={reverse ? 'true' : undefined}>
      {reverse ? (
        <>
          <span className={styles.text}>
            {label ? (
              <label htmlFor={id} id={labelId} className={styles.label}>
                {label}
              </label>
            ) : null}
            {description ? (
              <p id={descriptionId} className={styles.description}>
                {description}
              </p>
            ) : null}
          </span>
          {control}
        </>
      ) : (
        <>
          {control}
          <span className={styles.text}>
            {label ? (
              <label htmlFor={id} id={labelId} className={styles.label}>
                {label}
              </label>
            ) : null}
            {description ? (
              <p id={descriptionId} className={styles.description}>
                {description}
              </p>
            ) : null}
          </span>
        </>
      )}
    </div>
  )
}

@use 'styles' as vz;

.field {
  display: flex;
  align-items: flex-start;
  gap: vz.space(3);
}

.field[data-reverse='true'] {
  justify-content: space-between;
}

.switch {
  --switch-width: 2.75rem;
  --switch-height: 1.625rem;
  --switch-thumb: 1.25rem;

  position: relative;
  display: inline-flex;
  flex: none;
  align-items: center;
  width: var(--switch-width);
  height: var(--switch-height);
  padding: 2px;
  border: 0;
  border-radius: vz.radius('full');
  background: vz.color('foreground', 0.16);
  cursor: pointer;
  transition: background-color vz.duration('base') vz.ease('out');

  @include vz.focus-ring(2px, 2px, 0.6);

  @include vz.disabled {
    opacity: 0.45;
    pointer-events: none;
  }
}

.switch[aria-checked='true'] {
  background: vz.color('primary');
}

.thumb {
  display: block;
  width: var(--switch-thumb);
  height: var(--switch-thumb);
  border-radius: vz.radius('full');
  background: #fff;
  box-shadow: 0 1px 2px hsl(0deg 0% 0% / 20%);
  transform: translateX(0);
  transition: transform vz.duration('base') vz.ease('spring');

  @include vz.motion-reduce {
    transition: none;
  }
}

.switch[aria-checked='true'] .thumb {
  transform: translateX(calc(var(--switch-width) - var(--switch-thumb) - 4px));
}

.sm {
  --switch-width: 2.25rem;
  --switch-height: 1.375rem;
  --switch-thumb: 1rem;
}

.lg {
  --switch-width: 3.25rem;
  --switch-height: 1.875rem;
  --switch-thumb: 1.5rem;
}

.text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.label {
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 500;
  line-height: 1.35;
  cursor: pointer;
}

.description {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  line-height: 1.45;
}
